import { useEffect, useSyncExternalStore } from "react";

import type { CurFile } from "./Curriculum";
import { fetchCurriculumFile } from "./Curriculum";
import type { Card, Question } from "./data";
import { loadPdfLib } from "./PdfPage";
import { supabase } from "@/integrations/supabase/client";

/** Questions & flashcards generated by Wisen AI, saved to the student's account. */
type Row = { id: string; qtype: string; subject: string; unit: string; lesson: string; difficulty: string; stem: string; options: unknown; answers: unknown; explanation: string; source: string; origin: string };
export type AiQuestion = Question & { multi: boolean; origin: string; unit: string };

let qs: AiQuestion[] = [];
let cards: Card[] = [];
let snap = { qs, cards };
const subs = new Set<() => void>();
const emit = () => { snap = { qs, cards }; subs.forEach((f) => f()); };

/** MCQ answers are stored as a bitmask so a single number can be compared like an SCQ answer. */
export const mask = (idx: number[]) => idx.reduce((m, i) => m | (1 << i), 0);
export const isCorrectOption = (q: Question, k: number) => ((q as AiQuestion).multi ? ((q.answer >> k) & 1) === 1 : q.answer === k);

export function toQuestion(r: Row): AiQuestion {
  const options = (r.options as string[]) ?? [];
  const ans = ((r.answers as number[]) ?? [0]).map(Number);
  const multi = r.qtype === "MCQ";
  const d = ["Easy", "Medium", "Hard"].includes(r.difficulty) ? r.difficulty : "Medium";
  return { id: `ai-${r.id}`, subject: r.subject, topic: r.lesson || r.unit || r.subject, unit: r.unit, difficulty: d as Question["difficulty"], stem: r.stem, options, answer: multi ? mask(ans) : ans[0] ?? 0, why: r.explanation, distractors: [], slide: 0, source: r.source || undefined, multi, origin: r.origin };
}

async function load() {
  const { data: u } = await supabase.auth.getUser();
  if (!u.user) { qs = []; cards = []; emit(); return; }
  const [q, c] = await Promise.all([
    supabase.from("ai_questions").select("*").order("created_at"),
    supabase.from("ai_flashcards").select("*").order("created_at"),
  ]);
  qs = (q.data ?? []).map(toQuestion);
  cards = (c.data ?? []).map((x) => ({ id: `aic-${x.id}`, front: x.front, back: x.back, tip: x.tip || x.scope_label, topic: x.subject, source: x.scope_label }));
  emit();
}
export const reloadAi = load;
export const aiQuestions = () => qs;

export function useAi() {
  useEffect(() => {
    void load();
    const { data } = supabase.auth.onAuthStateChange((e) => { if (e === "SIGNED_IN" || e === "SIGNED_OUT") void load(); });
    return () => data.subscription.unsubscribe();
  }, []);
  return useSyncExternalStore((f) => { subs.add(f); return () => subs.delete(f); }, () => snap, () => snap);
}

/** Download course files and extract their text for Wisen AI (PDF only; other formats are skipped). */
export async function extractMaterial(files: CurFile[], maxFiles = 8, onProgress?: (done: number, total: number) => void) {
  const pick = files.filter((f) => /\.pdf$/i.test(f.file_name) || !/\.(pptx?|docx?|xlsx?|jpe?g|png)$/i.test(f.file_name)).slice(0, maxFiles);
  const out: { name: string; text: string }[] = [];
  const lib = await loadPdfLib();
  for (let i = 0; i < pick.length; i++) {
    onProgress?.(i, pick.length);
    try {
      const file = await fetchCurriculumFile(pick[i]!);
      const pdf = await lib.getDocument({ data: new Uint8Array(await file.arrayBuffer()) }).promise;
      let text = "";
      for (let n = 1; n <= pdf.numPages && text.length < 55000; n++) {
        const tc = await (await pdf.getPage(n)).getTextContent();
        text += `\n[Page ${n}] ` + tc.items.map((it) => ("str" in it ? it.str : "")).join(" ").replace(/\s+/g, " ");
      }
      if (text.trim().length > 50) out.push({ name: pick[i]!.file_name, text: text.slice(0, 55000) });
    } catch { /* skip unreadable */ }
  }
  onProgress?.(pick.length, pick.length);
  return out;
}

export async function fileText(f: File) {
  const lib = await loadPdfLib();
  const pdf = await lib.getDocument({ data: new Uint8Array(await f.arrayBuffer()) }).promise;
  let text = "";
  for (let n = 1; n <= pdf.numPages && text.length < 38000; n++) {
    const tc = await (await pdf.getPage(n)).getTextContent();
    text += `\n[Page ${n}] ` + tc.items.map((it) => ("str" in it ? it.str : "")).join(" ").replace(/\s+/g, " ");
  }
  return text.slice(0, 38000);
}
